// Wochenpreis wie die Vorschau: Band P10–P90, P50, Day-Ahead-Preis, je Tag um 12:00 das
// H0-gewichtete Tagesmittel (orange, an Ist-Tagen grün) mit rotem Fehlerbalken P10–P90 und auf
// Schalter das lastgewichtete Mittel (lila), Werte fett rechts neben den Punkten.
const data = context.panel.data;
const reihen = {};
let tage = null;
for (const f of data.series) {
  const zeit = f.fields.find((x) => x.type === 'time');
  if (!zeit) continue;
  if (f.refId === 'C') {
    tage = Object.fromEntries(f.fields.map((x) => [x.name, x.values]));
    continue;
  }
  for (const x of f.fields) {
    if (x.type !== 'number') continue;
    const name = x.labels?.metric || x.config?.displayNameFromDS || x.name;
    reihen[name] = zeit.values.map((t, i) => [t, x.values[i]]);
  }
}
const istPreis = reihen.da_price_de_lu || reihen.value || [];
const p10 = reihen.P10 || [];
const p90 = new Map((reihen.P90 || []).map(([t, v]) => [t, v]));
const fmt = (v) => (v == null ? '–' : v.toFixed(1));
const orange = '#ff9830', lila = '#b877d9', gruen = '#73bf69', rot = '#f2495c', blau = '#5794f2';
const h0 = [], fb = [], lastw = [];
if (tage) {
  tage.time.forEach((t, i) => {
    const ist = tage.ist?.[i];
    h0.push({ value: [t, tage.h0[i]], itemStyle: { color: ist ? gruen : orange },
              symbol: ist ? 'diamond' : 'circle', symbolSize: ist ? 14 : 12,
              label: { color: ist ? gruen : orange } });
    if (!ist && tage.h0_hi[i] > tage.h0_lo[i]) fb.push([t, tage.h0_lo[i], tage.h0_hi[i]]);
    if (tage.lastw?.[i] != null) lastw.push([t, tage.lastw[i]]);
  });
}
const hintergrund = context.grafana.theme.colors.background.primary;
const marke = { show: true, position: 'right', distance: 6, fontWeight: 'bold', fontSize: 14,
                textBorderColor: hintergrund, textBorderWidth: 3,
                formatter: (p) => fmt(p.value[1]) };
const datum = (t) => new Date(t).toLocaleDateString('de-DE', { weekday: 'short', day: '2-digit', month: '2-digit' });
const zeitpunkt = (t) => new Date(t).toLocaleString('de-DE', { weekday: 'short', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
const text = context.grafana.theme.colors.text;
const linie = context.grafana.theme.colors.border.weak;
// Erstellzeitpunkt des jüngsten gültigen Laufs (versteckte Dashboard-Variable je Modell)
const erstellt = context.grafana.replaceVariables('${lauf_preis_champion}');
return {
  backgroundColor: 'transparent',
  animation: false,
  graphic: [{
    type: 'group', right: 40, top: 6, z: 100,
    children: [
      { type: 'rect', shape: { width: 210, height: 24, r: 4 },
        style: { fill: hintergrund, stroke: linie, lineWidth: 1, opacity: 0.9 } },
      { type: 'text', left: 10, top: 5,
        style: { text: 'Prognose erstellt ' + erstellt, fill: text.primary, fontSize: 12 } },
    ],
  }],
  grid: { left: 60, right: 30, top: 36, bottom: 70 },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'line' },
    valueFormatter: (v) => (Array.isArray(v) ? '' : fmt(v) + ' €/MWh'),
    formatter: (ps) => {
      const zeilen = ps.filter((p) => !p.seriesName.startsWith('_') && p.value != null);
      return zeitpunkt(ps[0].axisValue) + '<br>' + zeilen.map((p) => {
        const v = Array.isArray(p.value) ? p.value[1] : p.value;
        const wert = p.seriesName === 'Band P10–P90' ? fmt(v) + ' – ' + fmt(p90.get(p.value[0]))
                                                    : fmt(v);
        return p.marker + p.seriesName + ': <b>' + wert + '</b> €/MWh';
      }).join('<br>');
    },
  },
  legend: { bottom: 0, textStyle: { color: text.secondary },
            data: ['Band P10–P90', 'Prognose P50', 'Day-Ahead-Preis', 'Tagesmittel H0',
                   'H0-Mittel P10–P90', ...(lastw.length ? ['Tagesmittel lastgewichtet'] : [])] },
  dataZoom: [{ type: 'inside', filterMode: 'none' }],
  xAxis: {
    type: 'time',
    min: data.timeRange.from.valueOf(),
    max: data.timeRange.to.valueOf(),
    splitNumber: 8,
    axisLabel: { color: text.secondary, formatter: (t) => datum(t), hideOverlap: true },
    splitLine: { show: true, lineStyle: { color: linie } },
  },
  yAxis: {
    type: 'value', scale: true, name: '€/MWh', nameLocation: 'middle', nameGap: 42,
    nameTextStyle: { color: text.secondary },
    axisLabel: { color: text.secondary }, splitLine: { lineStyle: { color: linie } },
  },
  series: [
    { name: '_unten', type: 'line', data: p10, stack: 'band', symbol: 'none',
      lineStyle: { opacity: 0 }, tooltip: { show: false } },
    { name: 'Band P10–P90', type: 'line', stack: 'band', symbol: 'none', color: '#9ca3af',
      lineStyle: { opacity: 0 }, areaStyle: { color: 'rgba(156,163,175,0.35)' },
      data: p10.map(([t, v]) => [t, p90.has(t) && v != null ? p90.get(t) - v : null]) },
    { name: 'Prognose P50', type: 'line', data: reihen.P50 || [], symbol: 'none', color: blau,
      lineStyle: { width: 2 } },
    { name: 'Day-Ahead-Preis', type: 'line', data: istPreis, symbol: 'none', color: gruen,
      lineStyle: { width: 1.5 } },
    { name: 'H0-Mittel P10–P90', type: 'custom', data: fb, color: rot, z: 4,
      tooltip: { show: false },
      renderItem: (params, api) => {
        const x = api.coord([api.value(0), api.value(1)])[0];
        const lo = api.coord([api.value(0), api.value(1)])[1];
        const hi = api.coord([api.value(0), api.value(2)])[1];
        const st = { stroke: rot, lineWidth: 1.5 };
        return { type: 'group', children: [
          { type: 'line', shape: { x1: x, y1: lo, x2: x, y2: hi }, style: st },
          { type: 'line', shape: { x1: x - 5, y1: lo, x2: x + 5, y2: lo }, style: st },
          { type: 'line', shape: { x1: x - 5, y1: hi, x2: x + 5, y2: hi }, style: st },
        ] };
      } },
    { name: 'Tagesmittel H0', type: 'scatter', data: h0, color: orange, z: 6,
      itemStyle: { borderColor: '#fff', borderWidth: 1 },
      label: { ...marke, offset: [0, -8] } },
    ...(lastw.length ? [{ name: 'Tagesmittel lastgewichtet', type: 'scatter', data: lastw,
      color: lila, symbol: 'triangle', symbolSize: 12, z: 5,
      itemStyle: { borderColor: '#fff', borderWidth: 1 },
      label: { ...marke, color: lila, offset: [0, 10] } }] : []),
  ],
};

